// Remove ONLY the four files generated by the earlier abandoned /stars/ shop
// installer, if their bytes are unchanged. Keep main Telegram Mini App untouched.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
const base=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../frontend/stars-shop');
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const names=['index.html','app.js','styles.css','config.js'];
async function main(){
 const arg=process.argv[2];
 if(!arg)throw Error('Pass your RUST-UP-Website checkout directory.');
 const project=await fs.realpath(path.resolve(arg));
 if(project.startsWith(root+path.sep))throw Error('separate_checkout_required');
 await fs.access(path.join(project,'.git'));
 const dir=path.join(project,'stars');
 let found;
 try{found=await fs.readdir(dir);}catch(e){
  if(e.code==='ENOENT'){console.log('PASS: No abandoned stars/ shop exists.');return;}
  throw e;
 }
 if(found.length!==names.length||names.some(name=>!found.includes(name)))
  throw Error('stars_folder_contains_other_files_refuse_delete');
 for(const name of names){
  const [original,current]=await Promise.all([
   fs.readFile(path.join(base,name)),fs.readFile(path.join(dir,name))
  ]);
  if(!original.equals(current))throw Error('stars_shop_modified_refuse_delete_'+name);
 }
 for(const name of names)await fs.unlink(path.join(dir,name));
 await fs.rmdir(dir);
 console.log('PASS: Only unchanged files from unused standalone /stars/ shop removed.');
 console.log('PASS: Existing Telegram Mini App and game files untouched.');
}
if(process.argv[1]&&pathToFileURL(path.resolve(process.argv[1])).href===import.meta.url)
 main().catch(e=>{console.error('Standalone shop cleanup BLOCKED:',e.message);process.exitCode=1;});
